								<a href="http://members.msn.com/oxygen360@yahoo.com" target="_blank"><img src="http://masslinemedia.com/smf/Themes/safgrey105/images/msntalk.gif" alt="oxygen360@yahoo.com" border="0" /></a>
								<a href="aim:goim?screenname=mattjay212503&amp;message=Hi.+Are+you+there?"><img src="http://masslinemedia.com/smf/Themes/safgrey105/images/aim.gif" alt="mattjay212503" border="0" /></a>
								<br />
								<a href="http://masslinemedia.com/smf/index.php?action=profile;u=929"><img src="http://masslinemedia.com/smf/Themes/safgrey105/images/icons/profile_sm.gif" alt="View Profile" title="View Profile" border="0" /></a>
								<a href="http://www.myspace.com/mattjayfilms" title="Mattjay" target="_blank"><img src="http://masslinemedia.com/smf/Themes/safgrey105/images/www_sm.gif" alt="WWW" border="0" /></a>
